css:
.gembasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2434;
    background: linear-gradient(165deg, #f4f1e9 0%, #ece6d6 100%);
    border-radius: 18px;
}

.gembasim-container * {
    box-sizing: border-box;
}

.gembasim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0d1b3e 0%, #16264f 55%, #1f3566 100%);
    color: #f5f1e6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(13, 27, 62, 0.32);
    border-bottom: 4px solid #c9a227;
}

.gembasim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.gembasim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0d98a;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.gembasim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4ddca;
}

.gembasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3a5e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.gembasim-period-counter #currentDay,
.gembasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0d1b3e;
}

.gembasim-round-name {
    background: #dfe6f2;
    color: #0d1b3e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.gembasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6e8c4;
    padding: 4px 12px;
    border-radius: 999px;
}

.gembasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.gembasim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1dac8;
    box-shadow: 0 4px 14px rgba(13, 27, 62, 0.07);
    border-top: 4px solid #1f3566;
}

.gembasim-card-esg { border-top-color: #2e7d4f; }
.gembasim-card-integration { border-top-color: #1f6f8b; }
.gembasim-card-balance { border-top-color: #6a4fb0; }
.gembasim-card-nps { border-top-color: #c9a227; }

.gembasim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7488;
}

.gembasim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0d1b3e;
}

.gembasim-card-esg .gembasim-value { color: #2e7d4f; }
.gembasim-card-integration .gembasim-value { color: #1f6f8b; }
.gembasim-card-balance .gembasim-value { color: #6a4fb0; }
.gembasim-card-nps .gembasim-value { color: #a9871a; }

.gembasim-sublabel {
    font-size: 0.76rem;
    color: #7c8497;
    line-height: 1.35;
}

.gembasim-nps-fail .gembasim-value { color: #c0392b; }
.gembasim-nps-ok .gembasim-value { color: #2e7d4f; }

.gembasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0d1b3e;
    color: #f1ecdc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.gembasim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0d98a;
}

.gembasim-budget-over #budgetDisplay,
.gembasim-budget-under #budgetDisplay {
    color: #ff9b8a;
}

.gembasim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(13, 27, 62, 0.05);
}

.gembasim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.gembasim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0d1b3e;
    margin-bottom: 6px;
}

.gembasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f3a52;
}

.gembasim-briefing-text strong { color: #2e7d4f; }
.gembasim-briefing-text em { color: #8a5a12; font-style: italic; }

.gembasim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1dac8;
    box-shadow: 0 4px 14px rgba(13, 27, 62, 0.07);
}

.gembasim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0d1b3e;
    border-bottom: 2px solid #efead9;
    padding-bottom: 8px;
}

.gembasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28324a;
    margin: 14px 0 6px;
}

.gembasim-container select,
.gembasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbc4ad;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f2;
    color: #1b2434;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.gembasim-container select:focus,
.gembasim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f3566;
    box-shadow: 0 0 0 3px rgba(31, 53, 102, 0.15);
}

.gembasim-container select option {
    background-color: #ffffff;
    color: #1b2434;
}

.gembasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a227;
}

.gembasim-range-readout,
.gembasim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f3566;
    margin-top: 4px;
}

.gembasim-range-readout span:last-child,
.gembasim-alloc-readout span:nth-child(2) {
    color: #2e7d4f;
    font-weight: 800;
}

.gembasim-hint {
    font-size: 0.8rem;
    color: #7c8497;
    margin-top: 4px;
    line-height: 1.4;
}

.gembasim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.gembasim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f4ea;
    border: 1px solid #e6dfc9;
    border-radius: 9px;
    padding: 8px 12px;
}

.gembasim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28324a;
}

.gembasim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.gembasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.gembasim-container .btn-primary {
    background: linear-gradient(135deg, #0d1b3e 0%, #1f3566 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f5f1e6;
    box-shadow: 0 6px 16px rgba(13, 27, 62, 0.28);
}

.gembasim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.gembasim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbc4ad;
    color: #6b7488;
}

.gembasim-coach {
    background: #0d1b3e;
    color: #f1ecdc;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(13, 27, 62, 0.24);
    border-left: 5px solid #c9a227;
}

.gembasim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d98a;
    margin-bottom: 8px;
}

.gembasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.gembasim-coach-body strong { color: #ffe08a; }
.gembasim-coach-body em { color: #ffc6a8; font-style: italic; }

.gembasim-history,
.gembasim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1dac8;
    box-shadow: 0 4px 14px rgba(13, 27, 62, 0.07);
}

.gembasim-history h3,
.gembasim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0d1b3e;
}

.gembasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28324a;
}

.gembasim-container table#usfHistoryTable th {
    background: #efead9;
    color: #0d1b3e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d8bf;
}

.gembasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efebdd;
}

.gembasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f0;
}

.gembasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .gembasim-container {
        padding: 14px;
    }
    .gembasim-header h1 {
        font-size: 1.7rem;
    }
    .gembasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .gembasim-value {
        font-size: 2rem;
    }
    .gembasim-clock {
        margin-left: 0;
    }
    .gembasim-period-counter {
        font-size: 0.88rem;
    }
    .gembasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .gembasim-alloc-row {
        flex-wrap: wrap;
    }
    .gembasim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .gembasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (gembasim) ---- */
.gembasim-completion { padding: 8px 4px 4px; }
.gembasim-cm-head { text-align: center; margin-bottom: 16px; }
.gembasim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6a5a; }
.gembasim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7ba99a; }
.gembasim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #1f2f2a; }
.gembasim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.gembasim-cm-yes { background: rgba(47,106,90,0.16); color: #2f6a5a; border: 1px solid rgba(47,106,90,0.5); }
.gembasim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.gembasim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.gembasim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(47,106,90,0.08); border: 1px solid rgba(47,106,90,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.gembasim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f6a5a; }
.gembasim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.gembasim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1f2f2a; }
.gembasim-cm-insights { margin: 0; padding-left: 20px; }
.gembasim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

