(function() {
    'use strict';

    class GembaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Lead Across Continents`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.HOUR_CAP = 480;            // fixed contact hours
            this.NPS_FLOOR = 40;            // contractual sponsor floor
            this.NPS_START = 47;            // last cohort
            this.SEATS_VALUE = 4.05;        // EUR 4.05M of contingent seats (2 intakes)
            this.SEATS = 31;               // of 72

            // Concept-correct play (the textbook answers). The seeded defaults are NOT this set.
            this.BEST = {
                principle: `integrate`,
                diagnosis: `boltedon`,
                model: `integrated`,
                assess: `graded`,
                residency: `terms`,
                thread: `capstone`,
                scorecard: `fourmetric`,
                evidence: `assessed`,
                sacrifice: `overlap`
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    esg: 20,
                    integration: 15,
                    balance: 25,
                    nps: this.NPS_START,
                    // current allocations (start = pre-redesign baseline)
                    coreHours: 320,
                    esgHours: 70,
                    regionalHours: 90,
                    barcelonaHours: 210,
                    saopauloHours: 150,
                    singaporeHours: 120,
                    hoursTotal: 480,
                    hoursOk: true,
                    npsBreached: false,
                    seatsRenew: false,
                    esgHistory: [20],
                    integrationHistory: [15],
                    balanceHistory: [25],
                    npsHistory: [this.NPS_START],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / NEUTRAL — a click-through must not auto-win.
                state.decisions = {
                    principle: `addmodule`,
                    diagnosis: `notenough`,
                    candor: 50,
                    core: 320,
                    esg: 70,
                    regional: 90,
                    model: `blended`,
                    assess: `reflection`,
                    barcelona: 210,
                    saopaulo: 150,
                    singapore: 120,
                    residency: `terms`,
                    thread: `handoff`,
                    faculty: 50,
                    scorecard: `esgonly`,
                    evidence: `hours`,
                    sacrifice: `vague`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const num = (id) => {
                const el = document.getElementById(id);
                return el ? Number(el.value) : NaN;
            };
            const val = (id, fallback) => {
                const el = document.getElementById(id);
                return el ? el.value : fallback;
            };

            if (round === 1) {
                decisions.principle = val(`principleInput`, decisions.principle);
                decisions.diagnosis = val(`diagnosisInput`, decisions.diagnosis);
                const c = num(`candorInput`);
                if (Number.isFinite(c)) decisions.candor = c;
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const core = num(`coreInput`);
                const esg = num(`esgInput`);
                const reg = num(`regionalInput`);
                if (Number.isFinite(core)) decisions.core = core;
                if (Number.isFinite(esg)) decisions.esg = esg;
                if (Number.isFinite(reg)) decisions.regional = reg;
                if (![decisions.core, decisions.esg, decisions.regional].every((v) => Number.isFinite(v) && v >= 0)) {
                    warn(`warn_hours_negative`); return false;
                }
                const total = decisions.core + decisions.esg + decisions.regional;
                if (total !== this.HOUR_CAP) {
                    warn(`warn_hours_total`); return false;
                }
                decisions.model = val(`modelInput`, decisions.model);
                decisions.assess = val(`assessInput`, decisions.assess);
            } else if (round === 3) {
                const bcn = num(`barcelonaInput`);
                const sp = num(`saopauloInput`);
                const sg = num(`singaporeInput`);
                if (Number.isFinite(bcn)) decisions.barcelona = bcn;
                if (Number.isFinite(sp)) decisions.saopaulo = sp;
                if (Number.isFinite(sg)) decisions.singapore = sg;
                if (![decisions.barcelona, decisions.saopaulo, decisions.singapore].every((v) => Number.isFinite(v) && v >= 0)) {
                    warn(`warn_hours_negative`); return false;
                }
                const total = decisions.barcelona + decisions.saopaulo + decisions.singapore;
                if (total !== this.HOUR_CAP) {
                    warn(`warn_regional_total`); return false;
                }
                decisions.residency = val(`residencyInput`, decisions.residency);
                decisions.thread = val(`threadInput`, decisions.thread);
                const f = num(`facultyInput`);
                if (Number.isFinite(f)) decisions.faculty = f;
                if (!Number.isFinite(decisions.faculty) || decisions.faculty < 0 || decisions.faculty > 100) {
                    warn(`warn_faculty_range`); return false;
                }
            } else if (round === 4) {
                decisions.scorecard = val(`scorecardInput`, decisions.scorecard);
                decisions.evidence = val(`evidenceInput`, decisions.evidence);
                decisions.sacrifice = val(`sacrificeInput`, decisions.sacrifice);
                const cv = num(`convictionInput`);
                if (Number.isFinite(cv)) decisions.conviction = cv;
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let esgDelta = 0, integrationDelta = 0, balanceDelta = 0, npsDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — DIAGNOSE: integration, not addition.
                // Design principle: integrate (best) > add a standalone module > protect-core-minimum > accumulate.
                switch (d.principle) {
                    case `integrate`:
                        integrationDelta += 13; esgDelta += 6; coachKey = `coach_r1_integrate`; break;
                    case `addmodule`:
                        esgDelta += 10; integrationDelta -= 6; coachKey = `coach_r1_addmodule`; break;
                    case `protectcore`:
                        integrationDelta -= 4; esgDelta -= 6; npsDelta += 1; coachKey = `coach_r1_protectcore`; break;
                    case `accumulate`:
                        integrationDelta -= 8; esgDelta += 2; coachKey = `coach_r1_accumulate`; break;
                }

                // Diagnosis: the bolt-on + incoherent-regions diagnosis is the highest-leverage one.
                switch (d.diagnosis) {
                    case `boltedon`:
                        integrationDelta += 9; balanceDelta += 6;
                        if (d.principle === `integrate`) coachKey = `coach_r1_sharp`;
                        break;
                    case `notenough`:
                        esgDelta += 3; integrationDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r1_notenough` : coachKey; break;
                    case `corequality`:
                        npsDelta -= 3; integrationDelta -= 4; coachKey = `coach_r1_corequality`; break;
                    case `nothing`:
                        esgDelta -= 6; integrationDelta -= 8; coachKey = `coach_r1_nothing`; break;
                }

                // Candor: willingness to redesign for integration, not just add hours.
                if (d.candor >= 60) { integrationDelta += 6; }
                else if (d.candor <= 25) { integrationDelta -= 6; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.principle === `integrate` && d.diagnosis === `boltedon`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — REBALANCE ESG and the core inside 480 hours.
                const core = d.core, esg = d.esg, reg = d.regional;
                const total = core + esg + reg;

                // Hour cap discipline (Common Error 3). Validation forces ==480, but guard anyway.
                ds.hoursOk = (total === this.HOUR_CAP);
                ds.coreHours = core; ds.esgHours = esg; ds.regionalHours = reg;
                if (total > this.HOUR_CAP) {
                    integrationDelta -= 12; coachKey = `coach_r2_overcap`;
                } else if (total < this.HOUR_CAP) {
                    integrationDelta -= 6; coachKey = `coach_r2_undercap`;
                }

                // ESG hours: under-funding ESG to protect the core (Common Error 2) reads as a refusal.
                // Credible band is ~110-150. Token (<=80) underperforms; gutting the core (>=200) hits NPS.
                if (esg >= 110 && esg <= 150) { esgDelta += 30; coachKey = `coach_r2_esgcredible`; }
                else if (esg >= 90 && esg < 110) { esgDelta += 20; }
                else if (esg > 150 && esg <= 180) { esgDelta += 26; }
                else if (esg > 180) { esgDelta += 26; coachKey = `coach_r2_esgoverload`; }
                else if (esg >= 71 && esg < 90) { esgDelta += 12; }
                else { esgDelta += 3; coachKey = `coach_r2_esgtoken`; } // <=70, barely more than today

                // Core satisfaction: cutting the 4.6/5 core too hard breaks the NPS floor (Common Error 6).
                if (core >= 270) { npsDelta += 2; }
                else if (core >= 240) { npsDelta -= 3; }
                else if (core >= 210) { npsDelta -= 7; coachKey = `coach_r2_corecut`; }
                else { npsDelta -= 12; coachKey = `coach_r2_corecut`; }

                // Delivery model: integrated (best) > blended > standalone bolt-on (Common Error 1).
                switch (d.model) {
                    case `integrated`: integrationDelta += 15; esgDelta += 5; coachKey = `coach_r2_integrated`; break;
                    case `blended`: integrationDelta += 9; esgDelta += 2; break;
                    case `standalone`: integrationDelta -= 8; esgDelta += 6; coachKey = `coach_r2_standalone`; break;
                }

                // Assessment: graded deliverable (best) evidences learning, not just exposure (Common Error 5).
                switch (d.assess) {
                    case `graded`: integrationDelta += 10; esgDelta += 4; coachKey = (d.model === `integrated`) ? `coach_r2_assessed` : coachKey; break;
                    case `reflection`: integrationDelta += 2; break;
                    case `attendance`: integrationDelta -= 14; coachKey = `coach_r2_noassess`; break;
                }

                summaryKey = (ds.hoursOk && esg >= 110 && esg <= 180 && core >= 240 && d.model !== `standalone` && d.assess === `graded`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Round 3 — BALANCE the three regions into one journey.
                const bcn = d.barcelona, sp = d.saopaulo, sg = d.singapore;
                ds.barcelonaHours = bcn; ds.saopauloHours = sp; ds.singaporeHours = sg;

                // Global balance: reward an even, coherent split; punish a lopsided skew (Common Error 4).
                const mean = this.HOUR_CAP / 3;
                const spread = (Math.abs(bcn - mean) + Math.abs(sp - mean) + Math.abs(sg - mean)) / mean;
                // spread 0 = perfectly even; baseline 210/150/120 ~ 0.56.
                if (spread <= 0.18) { balanceDelta += 24; coachKey = `coach_r3_balanced`; }
                else if (spread <= 0.35) { balanceDelta += 14; }
                else if (spread <= 0.55) { balanceDelta += 4; }
                else { balanceDelta -= 10; coachKey = `coach_r3_lopsided`; }

                // The sponsored Singapore residency: grabbing it tilts hours east (Common Error 4).
                switch (d.residency) {
                    case `terms`: balanceDelta += 10; integrationDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_terms` : coachKey; break;
                    case `decline`: balanceDelta += 6; break;
                    case `grab`:
                        balanceDelta -= 14; npsDelta += 1; coachKey = `coach_r3_grab`;
                        if (sg >= 180) balanceDelta -= 8; // doubled down on the tilt
                        break;
                }

                // Connective thread: a capstone across all three cities makes three residencies one journey.
                switch (d.thread) {
                    case `capstone`: balanceDelta += 16; integrationDelta += 4; coachKey = (d.residency === `terms` && spread <= 0.18) ? `coach_r3_journey` : coachKey; break;
                    case `handoff`: balanceDelta += 5; break;
                    case `none`: balanceDelta -= 10; coachKey = `coach_r3_nothread`; break;
                }

                // Faculty co-design: managing São Paulo resistance protects the redesign and satisfaction.
                if (d.faculty >= 60) { npsDelta += 4; integrationDelta += 2; }
                else if (d.faculty <= 25) { npsDelta -= 5; coachKey = `coach_r3_faculty`; }

                summaryKey = (spread <= 0.18 && d.residency !== `grab` && d.thread === `capstone`) ? `sum_r3_good` : (d.residency === `grab` ? `sum_r3_tilt` : `sum_r3_weak`);
            } else if (round === 4) {
                // Round 4 — DEFEND the design & set the scorecard.
                // Scorecard: all four metrics (best) > ESG-only > satisfaction-only.
                switch (d.scorecard) {
                    case `fourmetric`: balanceDelta += 8; integrationDelta += 5; esgDelta += 3; npsDelta += 2; coachKey = `coach_r4_fourmetric`; break;
                    case `esgonly`: esgDelta += 5; balanceDelta -= 6; npsDelta -= 3; coachKey = `coach_r4_esgonly`; break;
                    case `satisfaction`: npsDelta += 3; esgDelta -= 6; integrationDelta -= 6; coachKey = `coach_r4_satisfaction`; break;
                }

                // Evidence: assessed integration (best) proves capability; pointing at hours is exposure (Common Error 5).
                switch (d.evidence) {
                    case `assessed`: integrationDelta += 11; esgDelta += 6; coachKey = (d.scorecard === `fourmetric`) ? `coach_r4_assessed` : coachKey; break;
                    case `hours`: integrationDelta -= 10; esgDelta += 3; coachKey = `coach_r4_hours`; break;
                    case `intent`: integrationDelta -= 16; coachKey = `coach_r4_intent`; break;
                }

                // The cut you defend: naming the duplicated core hours + the principle (best) vs vague vs denial.
                switch (d.sacrifice) {
                    case `overlap`: integrationDelta += 6; npsDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_overlap` : coachKey; break;
                    case `vague`: integrationDelta -= 2; break;
                    case `nothing`: integrationDelta -= 8; npsDelta -= 4; coachKey = `coach_r4_nothing`; break;
                }

                // Conviction nudges the renewal case.
                integrationDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.scorecard === `fourmetric` && d.evidence === `assessed` && d.sacrifice === `overlap`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with 0-100 clamps on the three leading meters.
            ds.esg = Math.max(0, Math.min(100, ds.esg + esgDelta));
            ds.integration = Math.max(0, Math.min(100, ds.integration + integrationDelta));
            ds.balance = Math.max(0, Math.min(100, ds.balance + balanceDelta));
            // NPS floats around its floor; clamp to a sane executive range.
            ds.nps = Math.max(-20, Math.min(80, ds.nps + npsDelta));

            if (ds.nps < this.NPS_FLOOR) ds.npsBreached = true;

            ds.esgHistory.push(Math.round(ds.esg));
            ds.integrationHistory.push(Math.round(ds.integration));
            ds.balanceHistory.push(Math.round(ds.balance));
            ds.npsHistory.push(Math.round(ds.nps));

            // Final renewal verdict: the 31 seats renew only when all four hold up inside the cap.
            if (round === this.ROUNDS.length) {
                ds.seatsRenew = ds.esg >= 55 && ds.integration >= 60 && ds.balance >= 60 && ds.nps >= this.NPS_FLOOR && ds.hoursOk;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                esg: Math.round(ds.esg),
                esgDelta: Math.round(esgDelta),
                integration: Math.round(ds.integration),
                integrationDelta: Math.round(integrationDelta),
                balance: Math.round(ds.balance),
                balanceDelta: Math.round(balanceDelta),
                nps: Math.round(ds.nps),
                npsDelta: Math.round(npsDelta),
                npsBreached: ds.npsBreached,
                seatsRenew: ds.seatsRenew,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            const lang = () => (window.mySimulation && window.mySimulation.language) || `en`;

            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`esgDisplay`, `domainState.esg`, (v) => Math.round(Number(v)));
            uiManager.bind(`integrationDisplay`, `domainState.integration`, (v) => Math.round(Number(v)));
            uiManager.bind(`balanceDisplay`, `domainState.balance`, (v) => Math.round(Number(v)));
            uiManager.bind(`npsDisplay`, `domainState.nps`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.gembasim-card-nps`);
                if (card) {
                    card.classList.toggle(`gembasim-nps-fail`, n < self.NPS_FLOOR);
                    card.classList.toggle(`gembasim-nps-ok`, n >= self.NPS_FLOOR);
                }
                return (n >= 0 ? `+` : ``) + n;
            });
            uiManager.bind(`budgetDisplay`, `domainState.hoursTotal`, (v) => {
                const h = Math.round(Number(v));
                const bar = document.querySelector(`.gembasim-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`gembasim-budget-over`, h > self.HOUR_CAP);
                    bar.classList.toggle(`gembasim-budget-under`, h < self.HOUR_CAP);
                }
                return h + ` h / ` + self.HOUR_CAP + ` h`;
            });

            // Candor slider readout (R1).
            const candor = document.getElementById(`candorInput`);
            const candorReadout = document.getElementById(`candorReadout`);
            if (candor && candorReadout) {
                candorReadout.textContent = candor.value;
                candor.addEventListener(`input`, function() { candorReadout.textContent = candor.value; });
            }

            // Faculty slider readout (R3).
            const fac = document.getElementById(`facultyInput`);
            const facReadout = document.getElementById(`facultyReadout`);
            if (fac && facReadout) {
                facReadout.textContent = fac.value;
                fac.addEventListener(`input`, function() { facReadout.textContent = fac.value; });
            }

            // Topic-hour live total (R2) — must hit 480.
            const topicIds = [`coreInput`, `esgInput`, `regionalInput`];
            const hoursReadout = document.getElementById(`hoursReadout`);
            const recomputeTopic = function() {
                let total = 0;
                topicIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (Number(el.value) || 0);
                });
                if (hoursReadout) hoursReadout.textContent = total;
                const card = document.querySelector(`.gembasim-budget-bar`);
                if (card) card.classList.toggle(`gembasim-budget-over`, total !== self.HOUR_CAP);
                self._updateHoursDisplay(total);
            };
            topicIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeTopic);
            });

            // Regional-hour live total (R3) — must hit 480.
            const regionIds = [`barcelonaInput`, `saopauloInput`, `singaporeInput`];
            const regionalReadout = document.getElementById(`regionalReadout`);
            const recomputeRegion = function() {
                let total = 0;
                regionIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (Number(el.value) || 0);
                });
                if (regionalReadout) regionalReadout.textContent = total;
                self._updateHoursDisplay(total);
            };
            regionIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeRegion);
            });

            void lang;
        }

        _updateHoursDisplay(total) {
            const el = document.getElementById(`budgetDisplay`);
            if (el) el.textContent = total + ` h / ` + this.HOUR_CAP + ` h`;
            const bar = document.querySelector(`.gembasim-budget-bar`);
            if (bar) {
                bar.classList.toggle(`gembasim-budget-over`, total > this.HOUR_CAP);
                bar.classList.toggle(`gembasim-budget-under`, total < this.HOUR_CAP);
            }
        }

