        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.esgHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                gembaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.esgHistory },
                        { data: ds.integrationHistory },
                        { data: ds.balanceHistory },
                        { data: ds.npsHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const esg = Math.round(ds.esg);
            const integration = Math.round(ds.integration);
            const balance = Math.round(ds.balance);
            const nps = Math.round(ds.nps);
            return Math.max(0, Math.min(100, Math.round(esg * 0.28 + integration * 0.34 + balance * 0.24 + Math.max(0, Math.min(100, (nps + 20) * 1.25)) * 0.14)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const esg = Math.round(ds.esg);
            const integration = Math.round(ds.integration);
            const balance = Math.round(ds.balance);
            const nps = Math.round(ds.nps);

            const npsOk = nps >= this.NPS_FLOOR;
            const renew = esg >= 55 && integration >= 60 && balance >= 60 && npsOk && ds.hoursOk;
            const composite = this._composite(ds);

            let performance = window.mySimulation.t(`grade_atrisk`);
            if (renew && composite >= 78) performance = window.mySimulation.t(`grade_integrated`);
            else if (renew) performance = window.mySimulation.t(`grade_renewed`);
            else if (npsOk && integration >= 50 && esg >= 50) performance = window.mySimulation.t(`grade_unbalanced`);
            else if (!npsOk) performance = window.mySimulation.t(`grade_broken`);
            else if (integration < 40) performance = window.mySimulation.t(`grade_boltedon`);

            const insights = [];
            if (renew) insights.push(window.mySimulation.t(`insight_renew`));
            else insights.push(window.mySimulation.t(`insight_atrisk`));
            if (integration < 45) insights.push(window.mySimulation.t(`insight_boltedon`));
            if (!npsOk) insights.push(window.mySimulation.t(`insight_npsbreach`));
            if (balance < 50) insights.push(window.mySimulation.t(`insight_unbalanced`));
            if (!ds.hoursOk) insights.push(window.mySimulation.t(`insight_overcap`));
            if (renew && integration >= 70 && balance >= 70) insights.push(window.mySimulation.t(`insight_exemplar`));

            return {
                esg: esg,
                integration: integration,
                balance: balance,
                nps: nps,
                npsOk: npsOk,
                renew: renew,
                met: renew,
                npsBreach: !npsOk,
                overCap: !ds.hoursOk,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="gembasim-cm-badge gembasim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="gembasim-cm-badge gembasim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.npsBreach) failBadge += ` <span class="gembasim-cm-badge gembasim-cm-no">` + T(`cm_npsbreach`) + `</span>`;
            if (s.overCap) failBadge += ` <span class="gembasim-cm-badge gembasim-cm-no">` + T(`cm_overcap`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const npsv = Math.round(s.nps || 0); const npss = (npsv >= 0 ? `+` : ``) + npsv;
            const metrics = ``
                + `<div class="gembasim-cm-metric"><span class="gembasim-cm-mv">` + Math.round(s.esg || 0) + `</span><span class="gembasim-cm-ml">` + T(`cm_m_esg`) + `</span></div>`
                + `<div class="gembasim-cm-metric"><span class="gembasim-cm-mv">` + Math.round(s.integration || 0) + `</span><span class="gembasim-cm-ml">` + T(`cm_m_integration`) + `</span></div>`
                + `<div class="gembasim-cm-metric"><span class="gembasim-cm-mv">` + Math.round(s.balance || 0) + `</span><span class="gembasim-cm-ml">` + T(`cm_m_balance`) + `</span></div>`
                + `<div class="gembasim-cm-metric"><span class="gembasim-cm-mv">` + npss + `</span><span class="gembasim-cm-ml">` + T(`cm_m_nps`) + `</span></div>`;
            return ``
                + `<div class="gembasim-completion">`
                +   `<div class="gembasim-cm-head">`
                +     `<div class="gembasim-cm-score">` + score + `<span class="gembasim-cm-score-max">/100</span></div>`
                +     `<div class="gembasim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="gembasim-cm-metrics">` + metrics + `</div>`
                +   `<div class="gembasim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="gembasim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (!ds.hoursOk) return window.mySimulation.t(`hint_overcap`);
            if (ds.npsBreached || ds.nps < this.NPS_FLOOR) return window.mySimulation.t(`hint_nps`);
            if (ds.integration < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_integration`);
            if (ds.balance < 45 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_balance`);
            if (ds.esg < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_esg`);
            if (ds.esg >= 55 && ds.integration >= 60 && ds.balance >= 60 && ds.nps >= this.NPS_FLOOR) return window.mySimulation.t(`hint_strong`);
            return null;
        }

