                    alloc_core:             `Core management (finance, strategy, operations, leadership)`,
                    alloc_esg:              `ESG & sustainability hours`,
                    alloc_regional:         `Regional / elective hours`,
                    r2_hours_readout:       `Total hours allocated:`,
                    r2_hours_cap:           `/ 480 h`,
                    r2_model_label:         `How will ESG be delivered?`,
                    model_integrated:       `Integrated — ESG lives inside the finance, strategy and operations cases`,
                    model_blended:          `Blended — a small ESG anchor module plus integration across the core`,
                    model_standalone:       `Standalone — one visible ESG block the sponsors can point to`,
                    r2_assess_label:        `How will ESG learning be evidenced?`,
                    assess_graded:          `A graded, assessed deliverable embedded in core cases — proof of capability`,
                    assess_reflection:      `A reflective ungraded journal — exposure noted but not assessed`,
                    assess_attendance:      `Attendance only — count the hours scheduled, no assessment`,

                    r3_regional_label:      `Reallocate the regional hour split — must total exactly 480 hours`,
                    reg_barcelona:          `Barcelona — leadership & ESG`,
                    reg_saopaulo:           `São Paulo — strategy & finance`,
                    reg_singapore:          `Singapore — operations & digital`,
                    r3_regional_readout:    `Regional hours allocated:`,
                    r3_regional_cap:        `/ 480 h`,
                    r3_residency_label:     `A Singapore partner offers a sponsored operations residency — do you accept?`,
                    res_terms:              `Accept only on terms that preserve balance — cap the extra hours`,
                    res_decline:            `Decline — a free gift that tilts the programme east is not free`,
                    res_grab:               `Accept fully — free hours are free hours, push Singapore to 200`,
                    r3_thread_label:        `Design the connective thread across the three residencies`,
