                    thread_handoff:         `A light handoff brief between residencies`,
                    thread_none:            `No thread — three strong residencies will feel like one anyway`,
                    r3_faculty_label:       `How hard do you manage São Paulo faculty resistance to losing finance hours? (%)`,
                    r3_faculty_readout:     `Co-design and engagement with regional faculty:`,

                    r4_scorecard_label:     `What scorecard do you commit to the sponsor and the dean?`,
                    score_fourmetric:       `All four — global balance, ESG coverage, satisfaction AND employer relevance`,
                    score_esgonly:          `ESG coverage only — it is the renewal condition that matters`,
                    score_satisfaction:     `Satisfaction only — keep the participants and rankings happy`,
                    r4_evidence_label:      `When the sponsor probes whether ESG is assessed or merely scheduled, you show:`,
                    ev_assessed:            `Assessed integration — graded ESG deliverables inside core cases, with rubrics`,
                    ev_hours:               `The timetable — point to the ESG hours on the calendar`,
